#include <stdio.h>
#include <stdlib.h>

int compare(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int main() {
    int n, a, b;
    while (1) {
        scanf("%d %d %d", &n, &a, &b);
        if (n == 0 && a == 0 && b == 0) break;

        int h[n];
        for (int i = 0; i < n; i++) {
            scanf("%d", &h[i]);
        }

        qsort(h, n, sizeof(int), compare);

        int min_power = 1e9;

        // Try using k area spells
        for (int k = 0; k <= h[n-1] / b + 1; k++) {
            int remaining[n];
            int max_remaining = 0;
            for (int i = 0; i < n; i++) {
                int rem = h[i] - k * b;
                if (rem < 0) rem = 0;
                remaining[i] = rem;
                if (rem > max_remaining) max_remaining = rem;
            }

            // Now we need to kill remaining with single-target spells
            // worst-case: need max_remaining / a single spells on the biggest

            int single_needed = 0;
            for (int i = 0; i < n; i++) {
                if (remaining[i] > 0) {
                    single_needed += (remaining[i] + a - 1) / a;
                }
            }

            int total = k + single_needed;
            if (total < min_power) min_power = total;
        }

        printf("%d\n", min_power);
    }
    return 0;
}

