#define INF ((long long)4e18)

static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long*)a;
    long long y = *(const long long*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int n, m;
    while (scanf("%d %d", &n, &m) == 2) {
        if (n == 0 && m == 0) break;

        long long *h = (long long*)malloc(sizeof(long long) * n);
        long long *a = (long long*)malloc(sizeof(long long) * m);
        long long *b = (long long*)malloc(sizeof(long long) * m);

        for (int i = 0; i < n; i++) scanf("%lld", &h[i]);
        for (int i = 0; i < m; i++) scanf("%lld %lld", &a[i], &b[i]);

        qsort(h, n, sizeof(long long), cmp_ll);

        long long maxA = 0;
        long long minB = INF;
        for (int i = 0; i < m; i++) {
            if (a[i] > maxA) maxA = a[i];
            if (b[i] < minB) minB = b[i];
        }

        long long answer = INF;

        /* Try x times of all-target spell (using the cheapest one),
           then finish remaining monsters with the strongest single-target spell.
           It is sufficient to consider x around hp/maxB breakpoints, i.e. x = floor(h_i / minB)
           and x = floor(h_i / minB) + 1, plus x=0. */
        long long *cand = (long long*)malloc(sizeof(long long) * (2 * n + 2));
        int cc = 0;
        cand[cc++] = 0;
        for (int i = 0; i < n; i++) {
            long long t = h[i] / minB;
            cand[cc++] = t;
            cand[cc++] = t + 1;
        }

        qsort(cand, cc, sizeof(long long), cmp_ll);

        for (int i = 0; i < cc; i++) {
            if (i > 0 && cand[i] == cand[i - 1]) continue;
            long long x = cand[i];
            long long cost = x;

            long long need = 0;
            long long damage_all = x * minB;

            for (int j = 0; j < n; j++) {
                if (h[j] > damage_all) {
                    long long rem = h[j] - damage_all;
                    need += (rem + maxA - 1) / maxA;
                    if (cost + need >= answer) break;
                }
            }
            cost += need;
            if (cost < answer) answer = cost;
        }

        printf("%lld\n", answer);

        free(h);
        free(a);
        free(b);
        free(cand);
    }
    return 0;
}

