int main() {
    int n, B;
    while (cin >> n >> B) {
        if (n == 0 && B == 0) break;
        vector<int> h(n);
        for (int i = 0; i < n; i++) cin >> h[i];

        int maxH = *max_element(h.begin(), h.end());

        long long minCost = LLONG_MAX;
        // Try each possible AOE damage level x
        // Only need to check x = 0, 1, ..., maxH
        // But that could be large. Use sorted h and compute analytically.

        sort(h.begin(), h.end());

        // For a given x, cost = B*x + sum(max(0, h[i]-x))
        // Check at x = each h[i] and x = 0
        vector<int> candidates = {0};
        for (int v : h) candidates.push_back(v);

        for (int x : candidates) {
            long long cost = (long long)B * x;
            for (int i = 0; i < n; i++) {
                if (h[i] > x) cost += h[i] - x;
            }
            minCost = min(minCost, cost);
        }

        cout << minCost << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (true) {
        int n, m;
        if (!(cin >> n >> m)) return 0;
        if (n == 0 && m == 0) break;

        vector<int> hp(n);
        for (int i = 0; i < n; ++i) cin >> hp[i];

        const int INF = 1e9;
        vector<int> dp(1 << n, INF);
        dp[0] = 0;

        for (int i = 0; i < m; ++i) {
            string type;
            int cost, damage;
            cin >> type >> cost >> damage;

            vector<int> ndp = dp;

            if (type == "All") {
                for (int mask = 0; mask < (1 << n); ++mask) {
                    if (dp[mask] == INF) continue;
                    int nmask = mask;
                    for (int j = 0; j < n; ++j) {
                        if (!(mask & (1 << j)) && hp[j] <= damage) {
                            nmask |= (1 << j);
                        }
                    }
                    ndp[nmask] = min(ndp[nmask], dp[mask] + cost);
                }
            } else { // Single
                for (int mask = 0; mask < (1 << n); ++mask) {
                    if (dp[mask] == INF) continue;
                    for (int j = 0; j < n; ++j) {
                        if (!(mask & (1 << j)) && hp[j] <= damage) {
                            int nmask = mask | (1 << j);
                            ndp[nmask] = min(ndp[nmask], dp[mask] + cost);
                        }
                    }
                }
            }

            dp.swap(ndp);
        }

        int ans = dp[(1 << n) - 1];
        if (ans == INF) ans = -1;
        cout << ans << '\n';
    }

    return 0;
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNext()) {
            int n = sc.nextInt();
            int a = sc.nextInt();
            int b = sc.nextInt();
            if (n == 0 && a == 0 && b == 0) break;

            int[] hp = new int[n];
            int maxHp = 0;
            for (int i = 0; i < n; i++) {
                hp[i] = sc.nextInt();
                if (hp[i] > maxHp) maxHp = hp[i];
            }

            long ans = Long.MAX_VALUE;
            // try all possible number of all-target spells
            for (int k = 0; k <= maxHp; k++) {
                long cost = (long) k * b;
                for (int i = 0; i < n; i++) {
                    int remaining = hp[i] - k;
                    if (remaining > 0) {
                        cost += (long) remaining * a;
                    }
                }
                if (cost < ans) ans = cost;
            }
            System.out.println(ans);
        }
        sc.close();
    }
}

