import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }
            int a = fs.nextInt();
            int b = fs.nextInt();

            if (n == 0 && a == 0 && b == 0) break;

            int[] h = new int[n];
            int maxH = 0;
            long sumH = 0;
            for (int i = 0; i < n; i++) {
                h[i] = fs.nextInt();
                maxH = Math.max(maxH, h[i]);
                sumH += h[i];
            }

            // dp[x] = minimum MP to reduce a monster with x HP to 0
            long[] dp = new long[maxH + 1];
            dp[0] = 0;
            for (int x = 1; x <= maxH; x++) {
                long best = Long.MAX_VALUE / 4;

                // Single-target spell: deal a damage for cost 1
                best = Math.min(best, dp[Math.max(0, x - a)] + 1);

                // All-target spell: deal b damage to everyone for cost 1
                best = Math.min(best, dp[Math.max(0, x - b)] + 1);

                dp[x] = best;
            }

            long ans = 0;
            for (int hp : h) ans += dp[hp];

            /*
             * The intended interpretation for this classic problem is:
             * - Single-target spell deals A damage to one monster, cost 1
             * - All-target spell deals B damage to all monsters, cost 1
             *
             * Let k be the number of all-target casts.
             * Then each monster i has remaining HP max(0, h[i] - k*B),
             * which requires ceil(remaining / A) single-target casts.
             * Total cost = k + sum ceil(max(0, h[i]-kB)/A)
             *
             * We minimize over k.
             */

            long best = Long.MAX_VALUE;
            long limit = (maxH + b - 1L) / b;
            for (long k = 0; k <= limit; k++) {
                long cost = k;
                long damageAll = k * b;
                for (int hp : h) {
                    long rem = hp - damageAll;
                    if (rem > 0) {
                        cost += (rem + a - 1L) / a;
                    }
                    if (cost >= best) break;
                }
                best = Math.min(best, cost);
            }

            out.append(best).append('\n');
        }

        System.out.print(out.toString());
    }
}
